package com.oanarinaldi.wakemeup;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import android.content.*;import android.app.*;import android.os.*;import java.util.concurrent.*;import java.io.*;import org.json.*;
@RunWith(AndroidJUnit4.class)
public class WakeDeviceTest {
 ActivityScenario<MainActivity> scenario;MainActivity app;
 @Before public void open()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();c.getSharedPreferences("wake",0).edit().clear().commit();InstrumentationRegistry.getInstrumentation().getUiAutomation().grantRuntimePermission(c.getPackageName(),"android.permission.POST_NOTIFICATIONS");scenario=ActivityScenario.launch(MainActivity.class);scenario.onActivity(a->app=a);long end=System.currentTimeMillis()+15000;while(!app.loaded&&System.currentTimeMillis()<end)Thread.sleep(100);assertTrue(app.loaded);js("S.soundEnabled=false;S.welcomed=true;render();'ready'");}
 @After public void close(){RingService.stop(app);scenario.close();}
 String js(String s)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] out={null};scenario.onActivity(a->a.web.evaluateJavascript("{"+s+"}",r->{out[0]=r;latch.countDown();}));assertTrue(latch.await(10,TimeUnit.SECONDS));return out[0];}
 void truth(String s)throws Exception{assertEquals(s,"true",js(s));}
 void shot(String name)throws Exception{js("window.scrollTo(0,0);true");CountDownLatch frame=new CountDownLatch(1);scenario.onActivity(a->{a.web.scrollTo(0,0);a.web.invalidate();a.web.postVisualStateCallback(0,new android.webkit.WebView.VisualStateCallback(){public void onComplete(long id){frame.countDown();}});});assertTrue(frame.await(5,TimeUnit.SECONDS));Thread.sleep(600);File dir=new File(app.getExternalFilesDir(null),"screenshots");dir.mkdirs();try(var out=new FileOutputStream(new File(dir,name+".png"))){InstrumentationRegistry.getInstrumentation().getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
 @Test public void allScreensAndNoHorizontalOverflow()throws Exception{for(String tab:new String[]{"Morning","Move","Sunrises","Settings"}){js("tab="+JSONObject.quote(tab)+";screen='';render();true");truth("document.documentElement.scrollWidth<=innerWidth");shot(tab.toLowerCase());}for(String screen:new String[]{"tools","readiness","destinations","library","plus"}){js("openScreen("+JSONObject.quote(screen)+");true");truth("document.documentElement.scrollWidth<=innerWidth");shot(screen);}js("newAlarm();true");truth("document.querySelectorAll('[data-action^=step]').length===1");shot("alarm-editor");js("editingStep=0;screen='step';renderScreen();true");shot("route-step");js("screen='';action('practice:pushups');action('start');true");shot("challenge");js("pauseRitual();session=null;S.welcomed=false;screen='';render();true");shot("welcome");}
 @Test public void guidedChallengesRequireCorrectAnswersAndPracticeStaysSeparate()throws Exception{js("action('practice:math');action('start');true");shot("maths");js("document.querySelector('#answer').value='999';action('answerMath');true");truth("reps===0&&!session.finished");for(int i=0;i<3;i++){js("document.querySelector('#answer').value=String(mathQ.answer);action('answerMath');true");}truth("session.finished&&reps===3");shot("maths-complete");js("action('completeStep');true");truth("session===null&&S.sunrises.length===0");js("action('practice:words');action('start');document.querySelector('#answer').value='wrong';action('answerWords');true");truth("!session.finished");js("document.querySelector('#answer').value='TODAY I WILL START SMALL!';action('answerWords');true");truth("session.finished");js("action('completeStep');action('practice:memory');action('start');true");shot("memory");for(int i=0;i<3;i++){js("let seq=memory.seq.slice();action('memoryToggle');for(const x of seq)action('memoryTap:'+x);true");}truth("session.finished&&reps===3");js("action('completeStep');true");truth("S.sunrises.length===0");}
 @Test public void actualRouteRecoveryJournalAndWakeCheck()throws Exception{js("let a=C.alarm();a.route=[C.step('sunTaps'),C.step('words'),C.step('daylight')];a.wakeCheckMinutes=3;S.alarms=[a];startSession(a,false);action('start');true");for(int i=0;i<8;i++)js("action('sunTap:'+([0,3,1,2][reps%4]));true");truth("session.finished");js("action('completeStep');true");assertEquals(1,WakeData.read(app).getJSONObject("session").getInt("stepIndex"));js("action('start');document.querySelector('#answer').value=current().intention;action('answerWords');action('completeStep');action('start');action('selfAction');action('completeStep');true");truth("S.sunrises.length===1&&S.sunrises[0].steps.length===3&&S.wakeChecks.length===1");js("tab='Sunrises';render();true");shot("journal-completed");js("alarmArrived('check:'+S.wakeChecks[0].id);action('checkTap');action('checkTap');action('checkTap');true");truth("checkTaps===3");shot("wake-check");js("action('confirmAwake');true");truth("S.sunrises.length===1&&!!S.sunrises[0].wakeCheckConfirmedAt&&S.wakeChecks.length===0");}
 @Test public void soundImportIsBoundedAndDecodable()throws Exception{File source=new File(app.getCacheDir(),"test-tone.m4a"),out=new File(app.getCacheDir(),"test-trim.m4a");try(var in=app.getAssets().open("FirstLight.m4a");var stream=new FileOutputStream(source)){in.transferTo(stream);}MainActivity.trimAudio(source,out);android.media.MediaMetadataRetriever r=new android.media.MediaMetadataRetriever();r.setDataSource(out.getAbsolutePath());long duration=Long.parseLong(r.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION));assertTrue(duration>0&&duration<=25100);r.release();for(String tone:new String[]{"FirstLight","SoftStart","RiseAndShine","BrightMarimba","QuietKeys","MorningGroove"}){android.media.MediaPlayer player=new android.media.MediaPlayer();try(var fd=app.getAssets().openFd(tone+"Alarm.m4a")){player.setDataSource(fd.getFileDescriptor(),fd.getStartOffset(),fd.getLength());player.prepare();assertTrue(player.getDuration()>0);}finally{player.release();}}}
 @Test public void bundledCameraProcessorsWorkWithoutNetwork()throws Exception{try(var in=app.getAssets().open("movenet_lightning.tflite")){byte[] bytes=in.readAllBytes();java.nio.ByteBuffer model=java.nio.ByteBuffer.allocateDirect(bytes.length).order(java.nio.ByteOrder.nativeOrder());model.put(bytes).rewind();try(var interpreter=new org.tensorflow.lite.Interpreter(model,new org.tensorflow.lite.Interpreter.Options().setNumThreads(2))){int[] shape=interpreter.getInputTensor(0).shape();assertEquals(192,shape[1]);assertEquals(org.tensorflow.lite.DataType.UINT8,interpreter.getInputTensor(0).dataType());java.nio.ByteBuffer input=java.nio.ByteBuffer.allocateDirect(interpreter.getInputTensor(0).numBytes()).order(java.nio.ByteOrder.nativeOrder());float[][][][] output=new float[1][1][17][3];interpreter.run(input,output);assertTrue(Float.isFinite(output[0][0][5][2]));}}var matrix=new com.google.zxing.MultiFormatWriter().encode("wake-local-destination",com.google.zxing.BarcodeFormat.QR_CODE,240,240);int[] pixels=new int[240*240];for(int y=0;y<240;y++)for(int x=0;x<240;x++)pixels[y*240+x]=matrix.get(x,y)?0xff000000:0xffffffff;var result=new com.google.zxing.MultiFormatReader().decode(new com.google.zxing.BinaryBitmap(new com.google.zxing.common.HybridBinarizer(new com.google.zxing.RGBLuminanceSource(240,240,pixels))));assertEquals("wake-local-destination",result.getText());}
 @Test public void exactAlarmRingsAndSnoozeSurvivesRefresh()throws Exception{js("let a=C.alarm();a.id='device-alarm';a.snoozeMinutes=3;S.alarms=[a];save();true");AlarmScheduler.at(app,"device-alarm",System.currentTimeMillis()+1800);long end=System.currentTimeMillis()+12000;while(!WakeData.pending(app).equals("device-alarm")&&System.currentTimeMillis()<end)Thread.sleep(100);assertEquals("device-alarm",WakeData.pending(app));Thread.sleep(400);assertTrue(app.getSystemService(NotificationManager.class).getActiveNotifications().length>0);RingService.snooze(app,"device-alarm");long at=app.getSharedPreferences("wake",0).getLong("snooze:device-alarm",0);assertTrue(at>System.currentTimeMillis());assertTrue(java.util.Arrays.stream(app.getSystemService(NotificationManager.class).getActiveNotifications()).anyMatch(n->n.getId()=="device-alarm".hashCode()));AlarmScheduler.refresh(app);assertEquals(at,app.getSystemService(AlarmManager.class).getNextAlarmClock().getTriggerTime());AlarmScheduler.cancel(app,"device-alarm");}
}
